136	export function jobContextOperation(jobId: string, tenantId: string, principalId: string, requestId: string): Record<string, unknown> {
137	  const value: JobContextRecord = { id: jobId, jobId, tenantId, principalId, requestId, createdAt: new Date().toISOString() };
